                                         @PathVariable @NotBlank String linkId,
                                         @Valid @RequestBody ReceiptRequest request) {
        ReceiptRequest scoped = new ReceiptRequest(request.requestId(), channelId,
                request.generation(), request.seq());
        return service.submitReceipt(scoped).withLinkId(linkId);
    }

