 *
 * <p>同一频道同一时刻至多一条 ACTIVE 租约（数据库唯一索引强制）；租约世代单调递增。
 * 旧世代回执只存档为 LATE，不推进频道游标；新链路重复回执只结算一次。</p>
 */
@Service
public class FailoverService {

    public static final String OP_ACTIVATE_FAILOVER = "ACTIVATE_FAILOVER";
    public static final String OP_LINK_RECEIPT = "LINK_RECEIPT";

