public List<Long> findReceiptGaps(String channelId, String linkId, long generation,
                                  long throughSeq) {
    // 小序号集合内存比对，避免跨方言递归 CTE。
    List<Long> present = jdbc.queryForList("SELECT seq FROM playout_link_receipt"
                    + " WHERE channel_id = ? AND link_id = ? AND generation = ? AND seq <= ?"
                    + " ORDER BY seq",
            Long.class, channelId, linkId, generation, throughSeq);
    java.util.Set<Long> presentSet = new java.util.HashSet<>(present);
    List<Long> gaps = new java.util.ArrayList<>();
    for (long s = 1; s <= throughSeq; s++) {
        if (!presentSet.contains(s)) {
            gaps.add(s);
        }
    }
    return gaps;
}

