/**
 * 某链路在指定世代已缓存回执中的最大 seq（任意裁决），无回执时为 0。
 * 切换单创建时作为目标“最后回执 sequence”。
 */
public long maxReceiptSeq(String channelId, String linkId, long generation) {
    Long max = jdbc.queryForObject("SELECT COALESCE(MAX(seq), 0) FROM playout_link_receipt"
            + " WHERE channel_id = ? AND link_id = ? AND generation = ?",
            Long.class, channelId, linkId, generation);
    return max == null ? 0L : max;
}

/**
 * 某链路在指定世代已缓存回执的最长连续前缀：1..k 每个 seq 均存在（任意非空裁决），返回 k。
 * 逐条探测，序号集合通常很小；同时被 preview 的缺口检测复用。
 */
public long contiguousReceiptSeq(String channelId, String linkId, long generation) {
    long k = 0;
    while (receiptCount(channelId, linkId, generation, k + 1) > 0) {
        k++;
    }
    return k;
}

private int receiptCount(String channelId, String linkId, long generation, long seq) {
    Integer count = jdbc.queryForObject("SELECT COUNT(1) FROM playout_link_receipt"
                    + " WHERE channel_id = ? AND link_id = ? AND generation = ? AND seq = ?",
            Integer.class, channelId, linkId, generation, seq);
    return count == null ? 0 : count;
}

/**
 * 目标已缓存回执流中的缺口序号（升序）：(contiguousSeq, maxReceiptSeq] 内缺失的序号。
 * 即目标收到过更大的 seq 但中间有空洞（区别于只是尚未收到后续 seq 的“落后”）。
 */
public List<Long> findReceiptHoles(String channelId, String linkId, long generation,
                                   long contiguousSeq, long maxReceiptSeq) {
    List<Long> present = jdbc.queryForList("SELECT seq FROM playout_link_receipt"
                    + " WHERE channel_id = ? AND link_id = ? AND generation = ?"
                    + " AND seq > ? AND seq <= ? ORDER BY seq",
            Long.class, channelId, linkId, generation, contiguousSeq, maxReceiptSeq);
    java.util.Set<Long> presentSet = new java.util.HashSet<>(present);
    List<Long> holes = new java.util.ArrayList<>();
    for (long s = contiguousSeq + 1; s <= maxReceiptSeq; s++) {
        if (!presentSet.contains(s)) {
            holes.add(s);
        }
    }
    return holes;
}

